use oracle::ffi::{deflate_bytes, DeflateParams, Framing, Strategy};

fn xorshift(seed: &mut u64) -> u64 {
    *seed ^= *seed << 13;
    *seed ^= *seed >> 7;
    *seed ^= *seed << 17;
    *seed
}

fn main() {
    let mut seed = 12345u64;
    let strategies = [Strategy::Default, Strategy::Filtered, Strategy::HuffmanOnly, Strategy::Rle, Strategy::Fixed];
    let framings = [Framing::Raw, Framing::Zlib, Framing::Gzip];
    for trial in 0..25 {
        let len = 1 + (xorshift(&mut seed) % 16384) as usize;
        let is_pattern = xorshift(&mut seed) % 2 == 0;
        let data: Vec<u8> = if is_pattern {
            let plen = 1 + (xorshift(&mut seed) % 64) as usize;
            let pattern: Vec<u8> = (0..plen).map(|_| (xorshift(&mut seed) % 256) as u8).collect();
            pattern.iter().cycle().take(len).copied().collect()
        } else {
            (0..len).map(|_| (xorshift(&mut seed) % 256) as u8).collect()
        };
        let level = (xorshift(&mut seed) % 10) as u8;
        let strategy = strategies[(xorshift(&mut seed) % 5) as usize];
        let wb = 9 + (xorshift(&mut seed) % 7) as u8;
        let ml = 1 + (xorshift(&mut seed) % 9) as u8;
        let framing = framings[(xorshift(&mut seed) % 3) as usize];
