use cleanflate::{Decompressor, Format, Options, Status};

fn main() {
    let compressed = std::fs::read("/tmp/repro_compressed.bin").unwrap();
    let original = std::fs::read("/tmp/repro_original.bin").unwrap();
    println!("compressed_len={} original_len={}", compressed.len(), original.len());

    let mut d = Decompressor::new(Format::Raw, Options::default());
    let mut buf: Vec<u8> = Vec::new();
    let mut in_pos = 0usize;
    let mut iter = 0;
    loop {
        iter += 1;
        let cur_len = buf.len();
        let target_len = cur_len + 65536;
        buf.resize(target_len, 0);
        let remaining_input = &compressed[in_pos..];
        let write_region = &mut buf[cur_len..];
        let progress = d.decompress(remaining_input, write_region).unwrap();
        println!("iter={iter} in_pos_before={in_pos} consumed={} produced={} status={:?} remaining_input_len={}", progress.consumed, progress.produced, progress.status, remaining_input.len());
        in_pos += progress.consumed;
        buf.truncate(cur_len + progress.produced);
        match progress.status {
            Status::Done => break,
            Status::OutputFull => continue,
            Status::NeedsInput => {
                if progress.consumed == 0 {
                    println!("STOPPING: consumed==0, remaining_input_len_next={}", compressed.len()-in_pos);
                    break;
                }
            }
        }
        if iter > 50 { println!("too many iters"); break; }
    }
    println!("final buf len={} in_pos={} matches_original={}", buf.len(), in_pos, buf==original);
    match d.finish() {
        Ok(()) => println!("finish ok"),
        Err(e) => println!("finish err: {e:?}"),
    }
}
