fn format_of(row: &Row) -> Format {
    match row.format.as_str() {
        "zlib" => Format::Zlib,
        "gzip" => Format::Gzip,
        "raw" => Format::Raw,
        other => panic!("{}: unknown format {other:?}", row.path),
    }
